g.fill([73, 2, 9], [75, 2, 16], "oak_planks");
for (let y = 3; y <= 7; y++) {
  for (let z = 9; z <= 16; z++) for (const x of [73, 75]) g.set(x, y, z, "bamboo_fence");
  for (let x = 73; x <= 75; x++) { g.set(x, y, 9, "bamboo_fence"); g.set(x, y, 16, "bamboo_fence"); }
