for (let y = 3; y <= 7; y++) { g.set(73, y, 9, "stripped_oak_log"); g.set(75, y, 9, "stripped_oak_log"); }
g.set(74, 3, 9, "air"); g.set(74, 4, 9, "air");
g.save(outFile);
console.log("saved", outFile);
EOF
cd /Volumes/ext1/swe/repos/mc-design-eval/benchmarks/plugin-baseline/runs/build-1/polarton-kit/crew/part-20 && node /tmp/part20-test/shell-test.mjs build.nbt /tmp/part20-test/test.nbt && MCD=/Volumes/ext1/swe/repos/minecraft-design/tools/bin/mcd.mjs && node $MCD room /tmp/part20-test/test.nbt --rooms rooms.json --only "corn crib bin" 2>&1 | head -40

